<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import {hiddenLevels} from '../data/hidden-levels'
const arcade=useArcade(),chosen=ref(1),game=ref(null),busy=ref(false),error=ref(''),message=ref(''),hintId=ref(null),elapsed=ref(0),imageError=ref(false)
const config=computed(()=>hiddenLevels[chosen.value-1]),targets=computed(()=>game.value?.objects.filter(o=>o.target)??[]),clock=computed(()=>Math.floor(elapsed.value/60)+':'+String(elapsed.value%60).padStart(2,'0'))
let alive=true,version=0,hintTimer,clockTimer,startedAt=0
function stopTimers(){clearTimeout(hintTimer);clearInterval(clockTimer);hintId.value=null}
async function start(level=chosen.value){if(busy.value)return;busy.value=true;error.value='';const current=++version;stopTimers();try{const result=await api('/hidden/start',{method:'POST',body:{level,requestKey:crypto.randomUUID()}});if(!alive||current!==version)return;chosen.value=level;game.value=result;imageError.value=false;message.value='사진 속에서 아래 이모지 10개를 찾아 눌러 주세요!';elapsed.value=0;startedAt=Date.now();clockTimer=setInterval(()=>elapsed.value=Math.floor((Date.now()-startedAt)/1000),250)}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
async function action(type,object){if(busy.value||!game.value||game.value.done)return;busy.value=true;error.value='';const current=version,g=game.value;try{const result=await api('/hidden/'+g.id+'/action',{method:'POST',body:{action:type,objectId:object?.id}});if(!alive||current!==version)return;game.value=result;if(type==='hint'){hintId.value=result.hint;clearTimeout(hintTimer);hintTimer=setTimeout(()=>hintId.value=null,3000);message.value='반짝이는 동그라미를 살펴보세요!'}else if(type==='find'&&object.target){message.value=object.emoji+' 찾았어요!';if(hintId.value===object.id)hintId.value=null}else message.value='찾을 이모지 목록을 다시 확인해 보세요. 포인트는 줄어들지 않아요.';if(result.done){stopTimers();message.value='이모지 10개를 모두 찾았어요!';await arcade.refresh()}}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
function backgroundClick(event){if(event.target.closest('.hunt-object'))return;action('miss')}
function intro(){if(busy.value)return;version++;stopTimers();game.value=null;message.value='';error.value=''}
onMounted(()=>document.documentElement.classList.add('hidden-focus-mode'))
onUnmounted(()=>{alive=false;version++;stopTimers();document.documentElement.classList.remove('hidden-focus-mode')})
</script>
<template><section class="hidden-game"><p v-if="error" class="notice" role="alert">{{error}}</p><section v-if="!game" class="panel hunt-intro"><div class="hunt-intro-top"><div class="hunt-cover"><img src="/images/pixel-garden.png" alt="픽셀 정원"/><span aria-hidden="true">🔎</span><i aria-hidden="true">🍓</i><b aria-hidden="true">⭐</b></div><div><p class="eyebrow">SPOKEMON / EMOJI HUNT</p><h1>숨은그림 찾기</h1><p>사진 속에 꼭꼭 숨은 <strong>이모지 10개</strong>를 찾아요.<br/>10단계, 매 라운드 클리어 <strong>+3포인트!</strong></p><p class="hunt-rule">목록에 있는 이모지를 사진에서 찾아 누르세요. 힌트는 한 판에 3번, 제한 시간과 오답 감점은 없어요.</p></div></div><div class="hunt-levels" aria-label="숨은그림 단계 선택"><button v-for="level in hiddenLevels" :key="level.id" :class="{selected:chosen===level.id}" :aria-pressed="chosen===level.id" :disabled="busy" @click="chosen=level.id"><b>LEVEL {{level.id}}</b><span>{{level.name}}</span><small>10개 · +3 P</small></button></div><div class="hunt-intro-actions"><button :disabled="busy" @click="start()">{{busy?'준비 중…':'LEVEL '+chosen+' 시작 →'}}</button><RouterLink to="/" class="button light">메인으로</RouterLink></div><small>다시 시작하면 숨은 이모지와 위치가 바뀝니다. 다른 화면으로 이동하면 이번 게임은 초기화됩니다.</small></section><template v-else><header class="hunt-topbar"><div><p class="eyebrow">EMOJI HUNT · LEVEL {{chosen}}</p><h1>{{config.name}}</h1></div><div class="hunt-stats"><span>발견 <b>{{game.found.length}} / 10</b></span><span>시간 <b>{{clock}}</b></span><span>보상 <b>+3 P</b></span></div><div class="hunt-actions"><select :value="chosen" :disabled="busy" aria-label="숨은그림 단계" @change="start(Number($event.target.value))"><option v-for="level in hiddenLevels" :key="level.id" :value="level.id">LEVEL {{level.id}}</option></select><button class="light" :disabled="busy" @click="start()">↻ 재시작</button><button class="light" :disabled="busy" @click="intro">시작 화면</button></div></header><div class="hunt-workspace"><div class="hunt-board" :data-level="chosen" :style="{'--hunt-opacity':Math.max(.57,.94-chosen*.037),'--hunt-font':(30-Math.floor(chosen/3))+'px'}" @click="backgroundClick"><img class="hunt-background" :src="config.image" :alt="config.name+' 숨은그림 배경'" draggable="false" @error="imageError=true" @load="imageError=false"/><div class="hunt-photo-shade" aria-hidden="true"></div><button v-for="object in game.objects" :key="object.id" type="button" :class="['hunt-object',{found:game.found.includes(object.id),hint:hintId===object.id}]" :style="{left:object.x+'%',top:object.y+'%','--hunt-rotation':object.rotation+'deg'}" :data-object-id="object.id" :data-target="object.target" :disabled="busy||game.done||game.found.includes(object.id)" :aria-label="object.emoji+' 그림'+(game.found.includes(object.id)?' 발견 완료':' 찾기')" @click.stop="action('find',object)"><span>{{object.emoji}}</span><i v-if="game.found.includes(object.id)" aria-hidden="true">✓</i></button><p v-if="imageError" class="hunt-image-error" role="alert">사진을 불러오지 못했어요. 재시작해 주세요.</p><div v-if="game.done" class="hunt-clear"><div role="status"><p class="eyebrow">LEVEL CLEAR!</p><h2>{{chosen===10?'숨은그림 챔피언! 🏆':'10개 모두 찾았어요! 🎉'}}</h2><p>{{clock}} · 실수 {{game.misses}}번</p><strong>🪙 +3포인트 지급 완료!</strong><div class="hunt-clear-actions"><button v-if="chosen<10" :disabled="busy" @click="start(chosen+1)">다음 단계 →</button><button :disabled="busy" @click="start()">다시 찾기</button><RouterLink to="/" class="button light">메인으로</RouterLink></div></div></div></div><aside class="hunt-checklist panel"><div class="hunt-list-heading"><div><p class="eyebrow">FIND THEM ALL</p><h2>찾을 이모지 10개</h2></div><b>{{game.found.length}}/10</b></div><progress :value="game.found.length" max="10" aria-label="숨은그림 진행률"/><ul class="hunt-target-list"><li v-for="target in targets" :key="target.id" :class="{found:game.found.includes(target.id)}"><span>{{target.emoji}}</span><b>{{game.found.includes(target.id)?'✓':'?'}}</b></li></ul><button class="hunt-hint" :disabled="busy||game.done||!game.hintsLeft" @click="action('hint')">💡 힌트 {{game.hintsLeft}} / 3</button><p class="hunt-feedback" role="status">{{message}}</p><small>실수 {{game.misses}}번 · 포인트 감점 없음</small><RouterLink to="/" class="button light hunt-back">메인으로</RouterLink></aside></div></template></section></template>
<style scoped>
.hidden-game{min-width:0}.hunt-intro{padding:24px!important;max-width:1100px;margin:12px auto}.hunt-intro-top{display:grid;grid-template-columns:minmax(180px,.7fr) 1.5fr;gap:28px;align-items:center}.hunt-intro h1{font-size:32px;margin:10px 0}.hunt-intro p{font-size:14px;line-height:1.9}.hunt-rule{font-size:12px!important}.hunt-cover{height:180px;position:relative;overflow:hidden;border:3px solid var(--rpg-edge);border-radius:14px}.hunt-cover>img{width:100%;height:100%;object-fit:cover}.hunt-cover>span{position:absolute;left:35%;top:23%;font-size:66px}.hunt-cover>i{position:absolute;left:15%;top:60%;font-size:27px;font-style:normal}.hunt-cover>b{position:absolute;right:14%;top:22%;font-size:28px}.hunt-levels{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin:24px 0}.hunt-levels button{display:flex;flex-direction:column;gap:7px;align-items:center;padding:13px 6px!important;min-width:0}.hunt-levels b{font-size:14px}.hunt-levels span{font-size:11px}.hunt-levels small{font-size:10px}.hunt-intro-actions{display:flex;gap:14px;justify-content:center;margin:12px 0 16px}.hunt-intro>small{display:block;text-align:center;font-size:10px;line-height:1.7}.hunt-topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:10px 0 14px!important;border:0!important}.hunt-topbar h1{font-size:23px;margin:3px 0}.hunt-topbar .eyebrow{font-size:10px;margin:0}.hunt-stats{display:flex;gap:20px}.hunt-stats>span{font-size:11px;display:flex;flex-direction:column;gap:5px}.hunt-stats b{font-size:18px}.hunt-actions{display:flex;gap:8px;align-items:center}.hunt-actions button,.hunt-actions select{font-size:11px;padding:8px 9px}.hunt-actions select{background:var(--rpg-paper);color:var(--rpg-ink);border:2px solid var(--rpg-edge)}.hunt-workspace{display:grid;grid-template-columns:minmax(0,1fr) 235px;gap:15px;height:clamp(360px,calc(100dvh - 290px),680px);min-width:0}.hunt-board{position:relative;overflow:hidden;border:3px solid var(--rpg-edge);border-radius:10px;background:var(--rpg-soft);isolation:isolate;min-width:0;box-shadow:3px 4px var(--rpg-shadow)}.hunt-background{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none;user-select:none}.hunt-photo-shade{position:absolute;inset:0;background:linear-gradient(135deg,#2633460c,#17291a1c);pointer-events:none}.hunt-board .hunt-object{position:absolute!important;width:36px!important;height:36px!important;min-width:0!important;min-height:0!important;display:grid!important;place-items:center!important;padding:0!important;margin:0!important;border:0!important;background:transparent!important;box-shadow:none!important;text-shadow:none!important;color:inherit!important;transform:translate(-50%,-50%) rotate(var(--hunt-rotation))!important;translate:0 0!important;line-height:1!important;z-index:2;opacity:var(--hunt-opacity)!important;filter:none!important;touch-action:manipulation}.hunt-object>span{font-size:var(--hunt-font);font-family:'Segoe UI Emoji','Apple Color Emoji','Noto Color Emoji',sans-serif;filter:saturate(.75);pointer-events:none}.hunt-board .hunt-object.found{opacity:1!important;outline:3px solid #fff;border-radius:50%;background:#2c8556b8!important;transform:translate(-50%,-50%)!important}.hunt-object.found>span{opacity:.35}.hunt-object>i{position:absolute;color:#fff;font-size:22px;font-style:normal;text-shadow:0 2px 2px #153b25}.hunt-board .hunt-object.hint{outline:4px solid #ffdf40;outline-offset:4px;border-radius:50%;opacity:1!important;animation:hunt-pulse .6s infinite alternate;z-index:3}.hunt-checklist{padding:14px!important;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:12px}.hunt-list-heading{display:flex;align-items:center;justify-content:space-between;gap:5px}.hunt-list-heading h2{font-size:16px;margin:4px 0}.hunt-list-heading .eyebrow{font-size:9px;margin:0}.hunt-list-heading>b{font-size:20px}.hunt-checklist progress{width:100%;height:12px;flex-shrink:0}.hunt-target-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;list-style:none;padding:0;margin:0}.hunt-target-list li{display:flex;align-items:center;justify-content:space-around;min-height:42px;border:2px solid var(--rpg-mid);border-radius:7px;background:var(--rpg-soft)}.hunt-target-list li>span{font-size:25px;line-height:1.2;font-family:'Segoe UI Emoji','Apple Color Emoji',sans-serif}.hunt-target-list li>b{font-size:13px}.hunt-target-list .found{opacity:.5}.hunt-checklist .hunt-hint{font-size:12px;margin:0}.hunt-feedback{font-size:11px;line-height:1.7;min-height:35px;margin:0}.hunt-checklist small{font-size:9px}.hunt-back{font-size:11px;text-align:center}.hunt-clear{position:absolute;inset:0;z-index:5;background:#1730478c;display:grid;place-items:center;padding:15px}.hunt-clear>div{max-width:100%;max-height:100%;overflow:auto;padding:25px 18px;background:var(--rpg-paper);border:3px solid var(--rpg-edge);border-radius:14px;text-align:center;box-shadow:4px 5px var(--rpg-shadow)}.hunt-clear h2{font-size:23px}.hunt-clear p{font-size:12px}.hunt-clear strong{display:block;font-size:21px}.hunt-clear-actions{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:18px}.hunt-clear-actions button,.hunt-clear-actions .button{font-size:12px;padding:9px 12px}.hunt-image-error{position:absolute;top:0;left:0;right:0;background:#fff;padding:8px;z-index:4;font-size:12px}@keyframes hunt-pulse{to{outline-offset:9px;box-shadow:0 0 20px #ffe63c}}@media(prefers-reduced-motion:reduce){.hunt-board .hunt-object.hint{animation:none}}@media(max-width:800px){.hunt-topbar{flex-wrap:wrap}.hunt-topbar h1{font-size:19px}.hunt-actions{margin-left:auto}.hunt-workspace{grid-template-columns:minmax(0,1fr) 190px;gap:10px}.hunt-stats{gap:13px}.hunt-levels{gap:8px}.hunt-intro-top{gap:18px}}@media(max-width:600px){.hunt-intro{padding:15px!important}.hunt-intro-top{grid-template-columns:1fr;gap:8px}.hunt-cover{height:115px}.hunt-cover>span{font-size:52px;top:12%;left:41%}.hunt-intro h1{font-size:25px}.hunt-intro p{font-size:12px}.hunt-levels{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:16px 0}.hunt-levels button{padding:9px 5px!important;gap:4px}.hunt-levels b{font-size:12px}.hunt-levels span{font-size:10px}.hunt-topbar{gap:10px}.hunt-topbar>div:first-child{width:100%}.hunt-stats{gap:16px}.hunt-stats b{font-size:16px}.hunt-actions{flex-wrap:wrap;gap:6px;margin-left:0}.hunt-actions button,.hunt-actions select{font-size:10px;padding:7px}.hunt-workspace{display:flex;flex-direction:column;height:auto}.hunt-board{height:clamp(370px,54dvh,510px);flex:none}.hunt-board .hunt-object{width:34px!important;height:34px!important}.hunt-object>span{font-size:24px}.hunt-checklist{overflow:visible;gap:10px}.hunt-target-list{grid-template-columns:repeat(5,minmax(0,1fr));gap:6px}.hunt-target-list li{min-height:37px;position:relative}.hunt-target-list li>span{font-size:24px}.hunt-target-list li>b{position:absolute;right:2px;bottom:1px;font-size:10px}.hunt-feedback{min-height:0}.hunt-clear h2{font-size:19px}.hunt-clear strong{font-size:18px}.hunt-back{align-self:flex-start}.hunt-rule{font-size:11px!important}}
</style>
